var trim = function(v) {
  return v == null ? "" : String(v).trim();
};

var parseBoolean = function(v, defaultValue) {
  if (v == null) {
    return defaultValue;
  }
  var text = String(v).trim().toLowerCase();
  if (!text.length) {
    return defaultValue;
  }
  return text === "true" || text === "1" || text === "yes" || text === "on";
};

var parseInteger = function(v, defaultValue) {
  if (v == null) {
    return defaultValue;
  }
  var text = String(v).trim();
  if (!text.length) {
    return defaultValue;
  }
  try {
    var parsed = parseInt(text, 10);
    if (!isNaN(parsed)) {
      return parsed;
    }
  } catch (_ignoreParseInteger) {}
  return defaultValue;
};

var appendFiles = function(target, value) {
  if (value == null) {
    return;
  }
  var typeName = Object.prototype.toString.call(value);
  if (typeName === "[object Array]") {
    for (var ai = 0; ai < value.length; ai++) {
      appendFiles(target, value[ai]);
    }
    return;
  }
  var text = trim(value);
  if (!text.length) {
    return;
  }
  if (text.charAt(0) === "[") {
    try {
      var parsedArray = JSON.parse(text);
      if (Object.prototype.toString.call(parsedArray) === "[object Array]") {
        appendFiles(target, parsedArray);
        return;
      }
    } catch (_ignoreParseArray) {}
  }
  var chunks = text.split(/[\n,;]+/);
  for (var ci = 0; ci < chunks.length; ci++) {
    var itemText = trim(chunks[ci]);
    if (itemText.length) {
      target.push(itemText);
    }
  }
};

var startedAt = java.lang.System.currentTimeMillis();
var errorEntries = [];
var commandParts = [];
var normalizedFiles = [];
var outputText = "";
var truncatedFlag = false;
var exitCodeValue = -1;

var statusText = "error";
var messageText = "";
var successFlag = false;

var projectRootPath = "";
var scriptPath = "";
var pythonBin = trim(python);
var endpointText = trim(endpoint);
var protocolText = trim(protocol);
var timeoutText = trim(timeout);
var maxChars = parseInteger(maxOutputChars, 30000);
if (maxChars < 0) {
  maxChars = 0;
}
if (!pythonBin.length) {
  pythonBin = "python3";
}

var dryRunFlag = parseBoolean(dryRun, false);
var refreshFlag = parseBoolean(refresh, false);
var saveFlag = parseBoolean(save, false);
var structuralFlag = parseBoolean(structural, false);
var skipProjectCheckFlag = parseBoolean(skipProjectCheck, false);
var disableAutoBuildFlag = parseBoolean(disableAutoBuild, true);
var waitForCompletionRequestedFlag = parseBoolean(waitForCompletion, false);
var waitForCompletionFlag = waitForCompletionRequestedFlag;
var forcedAsyncReason = "";
var endpointLower = endpointText.toLowerCase();
var localEndpoint = !endpointLower.length
  || endpointLower.indexOf("://localhost:") >= 0
  || endpointLower.indexOf("://127.0.0.1:") >= 0;
if (waitForCompletionFlag && localEndpoint) {
  waitForCompletionFlag = false;
  forcedAsyncReason = "waitForCompletion forced to false for local MCP endpoint to avoid self-call timeout";
}
var asyncFlag = !waitForCompletionFlag;
var processPid = 0;
var logPath = "";

try {
  var projectRootText = trim(projectRoot);
  if (!projectRootText.length) {
    throw new Error("projectRoot is required");
  }
  var projectRootFile = new java.io.File(projectRootText).getCanonicalFile();
  if (!projectRootFile.exists()) {
    throw new Error("projectRoot does not exist: " + projectRootText);
  }
  var rootYaml = new java.io.File(projectRootFile, "c8oProject.yaml");
  if (!rootYaml.exists()) {
    throw new Error("projectRoot must contain c8oProject.yaml: " + String(projectRootFile.getPath()));
  }
  projectRootPath = String(projectRootFile.getPath());

  var currentProject = context && context.project ? context.project : null;
  if (currentProject == null) {
    throw new Error("No project context");
  }
  var wrapperProjectDir = new java.io.File(currentProject.getDirPath()).getCanonicalFile();
  var scriptFile = new java.io.File(wrapperProjectDir, "scripts/yaml_mcp_delta_apply.py").getCanonicalFile();
  if (!scriptFile.exists()) {
    throw new Error("Missing script: " + String(scriptFile.getPath()));
  }
  scriptPath = String(scriptFile.getPath());

  appendFiles(normalizedFiles, files);

  var command = new java.util.ArrayList();
  command.add(pythonBin);
  command.add(scriptPath);
  command.add(projectRootPath);

  if (normalizedFiles.length > 0) {
    command.add("--files");
    for (var fi = 0; fi < normalizedFiles.length; fi++) {
      command.add(String(normalizedFiles[fi]));
    }
  }
  if (dryRunFlag) {
    command.add("--dry-run");
  }
  if (refreshFlag) {
    command.add("--refresh");
  }
  if (saveFlag) {
    command.add("--save");
  }
  if (structuralFlag) {
    command.add("--structural");
  }
  if (skipProjectCheckFlag) {
    command.add("--skip-project-check");
  }
  if (disableAutoBuildFlag) {
    command.add("--disable-auto-build");
  }
  if (endpointText.length) {
    command.add("--endpoint");
    command.add(endpointText);
  }
  if (protocolText.length) {
    command.add("--protocol");
    command.add(protocolText);
  }
  if (timeoutText.length) {
    command.add("--timeout");
    command.add(timeoutText);
  }

  for (var k = 0; k < command.size(); k++) {
    commandParts.push(String(command.get(k)));
  }

  var builder = new java.lang.ProcessBuilder(command);
  builder.redirectErrorStream(true);

  if (waitForCompletionFlag) {
    var process = builder.start();

    var scanner = new java.util.Scanner(process.getInputStream(), "UTF-8").useDelimiter("\\A");
    var rawOutput = scanner.hasNext() ? String(scanner.next()) : "";
    scanner.close();

    exitCodeValue = process.waitFor();
    outputText = rawOutput;
    if (maxChars > 0 && outputText.length > maxChars) {
      outputText = outputText.substring(0, maxChars) + "\n...[truncated]";
      truncatedFlag = true;
    }

    successFlag = exitCodeValue === 0;
    statusText = successFlag ? "ok" : "failed";
    messageText = successFlag
      ? "yaml_mcp_delta_apply completed"
      : "yaml_mcp_delta_apply exited with code " + exitCodeValue;
  } else {
    var logFileText = trim(logFile);
    var logFile = null;
    if (logFileText.length) {
      var candidate = new java.io.File(logFileText);
      if (!candidate.isAbsolute()) {
        candidate = new java.io.File(wrapperProjectDir, logFileText);
      }
      logFile = candidate.getCanonicalFile();
    } else {
      var workDir = new java.io.File(wrapperProjectDir, "work");
      if (!workDir.exists()) {
        workDir.mkdirs();
      }
      logFile = new java.io.File(workDir, "yaml_delta_apply_" + startedAt + ".log").getCanonicalFile();
    }
    var parentDir = logFile.getParentFile();
    if (parentDir != null && !parentDir.exists()) {
      parentDir.mkdirs();
    }

    builder.redirectOutput(logFile);
    var processAsync = builder.start();
    try {
      processPid = Number(processAsync.pid());
    } catch (_ignorePid) {
      processPid = 0;
    }
    logPath = String(logFile.getPath());
    exitCodeValue = -1;
    outputText = "";
    successFlag = true;
    statusText = "started";
    messageText = "yaml_mcp_delta_apply started asynchronously";
    if (forcedAsyncReason.length) {
      messageText += " (" + forcedAsyncReason + ")";
    }
  }
} catch (runError) {
  var runMessage = String(runError);
  statusText = "error";
  messageText = runMessage;
  successFlag = false;
  errorEntries.push({ name: "run", message: runMessage });
}

var finishedAt = java.lang.System.currentTimeMillis();

resultStatus = statusText;
resultMessage = messageText;
resultSuccess = successFlag;
resultExitCode = exitCodeValue;
resultProjectRoot = projectRootPath;
resultScriptPath = scriptPath;
resultCommandText = commandParts.join(" ");
resultOutput = outputText;
resultTruncated = truncatedFlag;
resultDurationMs = finishedAt - startedAt;
resultTimestamp = finishedAt;
resultFilesCount = normalizedFiles.length;
resultFilesJson = JSON.stringify(normalizedFiles);
resultDryRun = dryRunFlag;
resultRefresh = refreshFlag;
resultSave = saveFlag;
resultStructural = structuralFlag;
resultSkipProjectCheck = skipProjectCheckFlag;
resultDisableAutoBuild = disableAutoBuildFlag;
resultWaitForCompletion = waitForCompletionFlag;
resultAsync = asyncFlag;
resultPid = processPid;
resultLogPath = logPath;
resultErrors = errorEntries;
